language "ix:native" edition "1-draft";
profile C = "quire.state.core/v1";
profile S = "quire.state.queries/v1";
profile G = "quire.state.graph/v1";
profile T = "quire.temporal.event-position.false-extension/v1";
profile F = "quire.temporal.fixed-sample.false-extension/v1";
profile W = "quire.temporal.timestamped-event.finite-window/v1";
profile P = "quire.protocol.finite-global/v1";
model M = "test/NativeEmission";
protocol Flow using P over (view: M::Plain) on origin {
                role Service on M::Node;
                requires temporal ByEvent;
                requires temporal BySample;
                requires temporal ByTimestamp;
                run sequence Main {
                    event Happened by Service as (happened: M::Plain) { happened.ready };
                }
                finish Closed as (closed: M::Plain) { closed.ready };
            }

